Exemplos
O exemplo a seguir demonstra a implementação da interface IList para criar uma lista simples de tamanho fixo.
using System;
using System.Collections;
class Program
{
static void Main()
{
var test = new SimpleList();
// Populate the List.
Console.WriteLine("Populate the List");
test.Add("one");
test.Add("two");
test.Add("three");
test.Add("four");
test.Add("five");
test.Add("six");
test.Add("seven");
test.Add("eight");
test.PrintContents();
Console.WriteLine();
// Remove elements from the list.
Console.WriteLine("Remove elements from the list");
test.Remove("six");
test.Remove("eight");
test.PrintContents();
Console.WriteLine();
// Add an element to the end of the list.
Console.WriteLine("Add an element to the end of the list");
test.Add("nine");
test.PrintContents();
Console.WriteLine();
// Insert an element into the middle of the list.
Console.WriteLine("Insert an element into the middle of the list");
test.Insert(4, "number");
test.PrintContents();
Console.WriteLine();
// Check for specific elements in the list.
Console.WriteLine("Check for specific elements in the list");
Console.WriteLine($"List contains \"three\": {test.Contains("three")}");
Console.WriteLine($"List contains \"ten\": {test.Contains("ten")}");
}
}
class SimpleList : IList
{
private object[] _contents = new object[8];
private int _count;
public SimpleList()
{
_count = 0;
}
// IList Members
public int Add(object value)
{
if (_count < _contents.Length)
{
_contents[_count] = value;
_count++;
return (_count - 1);
}
return -1;
}
public void Clear()
{
_count = 0;
}
public bool Contains(object value)
{
for (int i = 0; i < Count; i++)
{
if (_contents[i] == value)
{
return true;
}
}
return false;
}
public int IndexOf(object value)
{
for (int i = 0; i < Count; i++)
{
if (_contents[i] == value)
{
return i;
}
}
return -1;
}
public void Insert(int index, object value)
{
if ((_count + 1 <= _contents.Length) && (index <= Count) && (index >= 0))
{
_count++;
for (int i = Count - 1; i > index; i--)
{
_contents[i] = _contents[i - 1];
}
_contents[index] = value;
}
}
